from sklearn.compose import ColumnTransformer
from sklearn.ensemble import RandomForestClassifier, RandomForestRegressor
from sklearn.impute import SimpleImputer
from sklearn.pipeline import Pipeline
from sklearn.preprocessing import OneHotEncoder

def build_pipeline_e002(profile: dict):
    columns = profile['columns']
    numeric = [c['name'] for c in columns if c['kind'] == 'numeric']
    categorical = [c['name'] for c in columns if c['kind'] in ('categorical', 'boolean')]
    transformers = []
    if numeric:
        transformers.append(('num', SimpleImputer(strategy='median'), numeric))
    if categorical:
        cat = Pipeline([('impute', SimpleImputer(strategy='most_frequent')), ('onehot', OneHotEncoder(handle_unknown='ignore', sparse_output=False, max_categories=30))])
        transformers.append(('cat', cat, categorical))
    preprocess = ColumnTransformer(transformers, remainder='drop')
    if profile['problem_type'] == 'regression':
        model = RandomForestRegressor(random_state=42, n_estimators=100)
    else:
        model = RandomForestClassifier(random_state=42, n_estimators=100)
    return Pipeline([('preprocess', preprocess), ('model', model)])


def build_pipeline(profile):
    members = [
        ("e001", build_pipeline_e001(profile)),
        ("e005", build_pipeline_e005(profile)),
        ("e002", build_pipeline_e002(profile)),
    ]
    weights = None
    if profile["problem_type"] == "regression":
        return VotingRegressor(members, weights=weights)
    return VotingClassifier(members, voting="soft", weights=weights)
